chrome.tabs.query({}, 
	function(tabs){
		let tabFound = false;
		
		tabs.every( tab => 
		{
			console.log(tab.url, '匹配结果:', tab.url.startsWith('{url}'));
			
			if (tab.url.startsWith('{url}'))
			{
				tabFound = true;
				chrome.windows.update(tab.windowId, {focused: true}, 	
	                (window) => {chrome.tabs.update(tab.id, {active: true});}
	                );
	             
	             return false;
            }
            
            return true;
	    });
	    
	    
	    if (!tabFound){
			chrome.tabs.create({url: '{url}'});
		}
		
});"},"waitComplete":{"VarKey":null,"Value":"1"},"stopIfFail":{"VarKey":null,"Value":"1"},"timeoutMs":{"VarKey":null,"Value":"3000"}},"OutputParams":{"isSuccess":null,"rawResponse":null},"IfSteps":null,"ElseSteps":null,"Note":"","Disabled":false,"Collapsed":false,"DelayMs":0}]}
